-- ========================================================
-- Table: detections
-- ========================================================
DROP TABLE IF EXISTS detections;
CREATE TABLE detections (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    track_id        INTEGER,
    raw_track_id    INTEGER,
    camera_id       TEXT NOT NULL,
    mode            TEXT NOT NULL,
    timestamp       TEXT NOT NULL,
    bbox            TEXT NOT NULL,             -- JSON [x1,y1,x2,y2]
    confidence      REAL,
    crop_path       TEXT,
    upper_garment   TEXT,
    lower_garment   TEXT,
    gender          TEXT,
    gender_conf     REAL,
    upper_hist      BLOB,                      -- float32 HSV histogram, L2-normalized
    lower_hist      BLOB,                      -- float32 HSV histogram, L2-normalized
    extra           TEXT                       -- JSON for anything else
, last_seen TEXT, frame_count INTEGER DEFAULT 1, first_seen TEXT);

CREATE INDEX idx_det_ts ON detections(timestamp);
CREATE INDEX idx_det_cam ON detections(camera_id);
CREATE INDEX idx_det_track ON detections(track_id, camera_id);
CREATE INDEX idx_det_gender ON detections(gender);

-- Insert rows for detections (146 records)


-- ========================================================
-- Table: garment_colors
-- ========================================================
DROP TABLE IF EXISTS garment_colors;
CREATE TABLE garment_colors (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    detection_id    INTEGER NOT NULL REFERENCES detections(id) ON DELETE CASCADE,
    slot            TEXT NOT NULL CHECK (slot IN ('upper','lower')),
    rank            INTEGER NOT NULL,          -- 0 = primary, 1 = secondary, ...
    color_name      TEXT NOT NULL,
    percentage      REAL NOT NULL,
    rgb             TEXT                       -- JSON [r,g,b]
);

CREATE INDEX idx_color_slot_name ON garment_colors(slot, color_name);
CREATE INDEX idx_color_det ON garment_colors(detection_id);

