-- ========================================================
-- Table: face_embeddings
-- ========================================================
DROP TABLE IF EXISTS face_embeddings;
CREATE TABLE face_embeddings (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    track_id        INTEGER,
    camera_id       TEXT NOT NULL,
    detection_id    INTEGER REFERENCES detections(id) ON DELETE SET NULL,
    timestamp       TEXT NOT NULL,
    vector          BLOB NOT NULL,             -- float32[512], L2-normalized
    det_confidence  REAL,
    quality         REAL,                      -- composite score in [0,1]
    face_crop_path  TEXT
);

CREATE INDEX idx_face_track ON face_embeddings(track_id, camera_id);
CREATE INDEX idx_face_ts ON face_embeddings(timestamp);

